(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*12+Math.cos(y*0.013-t*0.18)*8;
  const w2 = Math.cos(x*0.012-t*0.15)*10+Math.sin(y*0.02+t*0.22)*14;
  const sx = x+w1, sy = y+w2;
  const dx = Math.sin(sx*0.025+t*0.1)*6, dy = Math.cos(sy*0.025-t*0.12)*6;
  const fx = sx+dx, fy = sy+dy;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2, 0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 1],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 2],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4, 3],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 4],
    [240+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.5)*85, 0.08, 2.0, 5],
    [60+Math.sin(t*0.6+3)*70, 100+Math.cos(t*0.4+4)*60, 0.1, 1.6, 6],
    [420+Math.cos(t*0.33+1)*75, 140+Math.sin(t*0.65+2)*70, 0.075, 2.4, 7]
  ];
  let aS=0, iS=0, act2=0, inh2=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const w=Math.sin(d*f-t*sp+ph)*Math.exp(-d*0.002);
    aS+=w; iS+=Math.sin(d*f*0.65+t*sp*0.55+ph+1.8);
    act2+=Math.sin(d*f*1.3-t*sp*1.1+ph*0.5)*Math.exp(-d*0.003);
    inh2+=Math.cos(d*f*0.8+t*sp*0.4-ph)*Math.exp(-d*0.0025);
  }
  const n=8, act=aS/n, inh=iS/n, a2=act2/n, i2=inh2/n;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.035+t*0.95))/2;
  const bg2=Math.sin((fx+fy)*0.11+t*2.2)*0.25+Math.sin((fx-fy)*0.09-t*1.8)*0.25;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const turb=Math.sin(fx*0.08+fy*0.06+t*1.5)*Math.sin(fx*0.06-fy*0.09-t*1.2)*0.4;
  const lap = (a2-inh2)*0.5;
  const rd = act - inh*0.65 + bg*0.2 + bg2 + spiral + turb + lap*0.8;
  const reaction = Math.tanh(rd*2.0);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4+Math.sin((fx-fy)*0.07-t*0.8)*0.3)*1.8)*0.25;
  const micro = Math.sin(fx*0.3+t*3)*Math.sin(fy*0.3-t*2.5)*0.08;
  const blend = reaction*0.7 + cell*0.22 + micro;
  const v = blend*0.5+0.5;
  const edge = Math.pow(Math.abs(reaction),1.5)*0.3;
  const glow = Math.max(0, Math.sin(reaction*Math.PI*1.5))*0.15;
  const pal = [
    [6,12,52],[10,35,82],[14,65,115],[18,110,140],[28,158,148],
    [140,185,120],[210,195,80],[225,145,65],[210,95,60],[175,55,55],
    [130,30,48],[75,18,42],[40,12,35],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow;
  const ef=1.0+edge;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*ef))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*ef))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*ef))|0
  ];
}
